public protocol YmClientProtocol: AnyObject, Sendable {
    
    func home() async throws  -> FfiHome
    
    func likedAlbums() async throws  -> [FfiAlbum]
    
    func likedArtists() async throws  -> [FfiArtist]
    
    /**
     * Ids of liked tracks, newest first. One light request (no track models).
     */
    func likedIds() async throws  -> [String]
    
    func likedTracks() async throws  -> [FfiTrack]
    
    func myPlaylists() async throws  -> [FfiPlaylist]
    
    /**
     * Report a listen to the service (`/play-audio`) so history and recommendations follow.
     */
    func reportPlay(trackId: String, albumId: String?, durationSeconds: Double, playedSeconds: Double, fromCache: Bool) async throws 
    
    func search(query: String) async throws  -> FfiSearch
    
    func setLiked(trackId: String, liked: Bool) async throws 
    
    /**
     * Resolve a playable stream.
     *
     * - `quality`: `lossless` (FLAC) | `hq` (AAC 256) | `nq` (AAC 192) | `lq` (HE-AAC 64).
     * - `codecs`: acceptable codecs, empty = every codec the API knows.
     * - `key` in the result is set only for encrypted (`encraw`) streams.
     *
     * The API itself has no "lq" quality: the 64 kbit/s HE-AAC file is what it serves when the
     * client accepts nothing but `he-aac-mp4`. If that one is missing we fall back to `nq`.
     */
    func streamUrl(trackId: String, quality: String, codecs: [String]) async throws  -> FfiStream
    
    /**
     * `kind`: liked | history | playlist ("uid:kind") | album | artist.
     */
    func tracksOf(kind: String, id: String) async throws  -> [FfiTrack]
    
    /**
     * `kind`: radioStarted | trackStarted | trackFinished | skip | like | dislike.
     */
    func waveFeedback(stationId: String, trackId: String?, kind: String, playedSeconds: Double) async throws 
    
    /**
     * Next batch for a station. Creates (and caches) a rotor session on first use.
     */
    func waveTracks(stationId: String, queue: [String]) async throws  -> [FfiTrack]
    
}
